void NativeOpencordMobile::registerModule(
    jsi::Runtime &rt, std::shared_ptr<react::CallInvoker> callInvoker) {
  auto invoker =
      std::make_shared<uniffi_runtime::UniffiCallInvoker>(callInvoker);
  auto tm = std::make_shared<NativeOpencordMobile>(rt, invoker);
  auto obj = rt.global().createFromHostObject(rt, tm);
  rt.global().setProperty(rt, "NativeOpencordMobile", obj);
}

void NativeOpencordMobile::unregisterModule(jsi::Runtime &rt) {
  uniffi::opencord_mobile::registry::clearRegistry();
}

jsi::Value NativeOpencordMobile::get(jsi::Runtime &rt,
                                     const jsi::PropNameID &name) {
  try {
    return jsi::Value(rt, props.at(name.utf8(rt)));
  } catch (std::out_of_range &) {
    return jsi::Value::undefined();
  }
}

std::vector<jsi::PropNameID>
NativeOpencordMobile::getPropertyNames(jsi::Runtime &rt) {
  std::vector<jsi::PropNameID> rval;
  for (auto &[key, value] : props) {
    rval.push_back(jsi::PropNameID::forUtf8(rt, key));
  }
  return rval;
}

void NativeOpencordMobile::set(jsi::Runtime &rt, const jsi::PropNameID &name,
                               const jsi::Value &value) {
  props.insert_or_assign(name.utf8(rt), &value);
}

